// Turn n8n's error report into one short message for the owner, plus a row for the error log.
const OWNER_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
const e = $input.first().json;
const ex = e.execution || {};
const wf = e.workflow || {};
const err = ex.error || e.trigger && e.trigger.error || {};
const message = String(err.message || err.description || 'Unknown error').slice(0, 300);
const nodeName = ex.lastNodeExecuted || (err.node && err.node.name) || 'unknown step';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = '🚨 <b>Market Report: something broke</b>\n' +
  'Workflow: ' + esc(wf.name || 'unknown') + '\n' +
  'Step: ' + esc(nodeName) + '\n' +
  'Error: ' + esc(message) + '\n' +
  (ex.url ? 'Details: ' + esc(ex.url) : '');
return [{ json: {
  owner_chat_id: OWNER_CHAT_ID,
  text: text,
  workflow: wf.name || 'unknown',
  node: nodeName,
  message: message,
  created_at: new Date().toISOString()
} }];
